 public sealed class Meter:Surface {
  public readonly Engine Engine;bool shuttingDown;History history;Compact compact;HwndSource source;
  TextBlock status,map,region,rate,level,percent,eta,gain,average,time,loss;Border progress;Button start;MinuteGraph chart;
  public Meter(bool demo=false):base("MapleMeter 暖光版",640,650){Engine=new Engine(demo);Build();Engine.Updated+=Refresh;App.FontChanged+=Rebuild;Loaded+=delegate{Engine.Start();};SourceInitialized+=delegate{source=HwndSource.FromHwnd(new WindowInteropHelper(this).Handle);source.AddHook(Hook);Native.RegisterHotKey(source.Handle,1,0x4000|2|1,0x20);Native.RegisterHotKey(source.Handle,2,0x4000|2|1,0x4c);};Closing+=delegate(object sender,System.ComponentModel.CancelEventArgs e){try{if(Engine.Session.Running)Engine.EndSession();}catch(Exception ex){MessageBox.Show(this,"保存失败，记录仍保留："+ex.Message);e.Cancel=true;}};Closed+=delegate{shuttingDown=true;App.FontChanged-=Rebuild;Engine.Updated-=Refresh;if(source!=null){Native.UnregisterHotKey(source.Handle,1);Native.UnregisterHotKey(source.Handle,2);source.RemoveHook(Hook);}if(history!=null)history.Close();if(compact!=null)compact.Close();Engine.Dispose();};}
  IntPtr Hook(IntPtr hwnd,int msg,IntPtr w,IntPtr l,ref bool handled){if(msg==0x312){if(w.ToInt32()==1)Engine.TogglePause();if(w.ToInt32()==2)ReturnToMain();handled=true;}return IntPtr.Zero;}
  void Rebuild(){Build();Refresh();}
  TextBlock Cell(string value,double font,double x,double y,double w,double h,Brush color=null,bool bold=false,bool latin=false,TextAlignment align=TextAlignment.Left){var text=App.Text(value,font,color,bold,latin);text.TextAlignment=align;return App.At(canvas,text,x,y,w,h);}
  void Build(){Reset();Header("MapleMeter 暖光版");App.At(canvas,new Ellipse{Fill=App.Green},270,18,8,8);status=Cell("等待游戏",12,285,7,160,30,App.Green);
   var banner=new Grid{Clip=new RectangleGeometry(new Rect(0,0,600,92),12,12),Background=App.Gradient("#FFF0D9","#FBE7C9")};string path=System.IO.Path.Combine(App.Dir,"banner.png");if(Theme.Warm&&File.Exists(path))banner.Children.Add(new Image{Source=Assets.Banner,Stretch=Stretch.UniformToFill});if(Theme.Warm)banner.Children.Add(new Rectangle{Fill=new LinearGradientBrush(new GradientStopCollection{new GradientStop(Color.FromArgb(165,255,245,228),0),new GradientStop(Color.FromArgb(0,255,245,228),.75)},0)});App.At(canvas,banner,20,48,600,92);
   App.At(canvas,(FrameworkElement)App.Icon("pin",28,App.Brush("#EE8553")),38,78);map=Cell("等待地图",20,82,60,390,36,null,true);region=Cell("",13,83,98,390,24,App.Muted,false,true);
   App.At(canvas,App.Card(),20,150,332,145);App.At(canvas,App.Card(),364,150,256,145);Cell("预计每小时经验",12,38,160,296,24,App.Muted);rate=Cell("—",54,38,187,296,66,Theme.Dark?App.Green:App.Ink,true,true);Cell("按最近 5 分钟效率估算",12,38,257,296,24,App.Muted);
   level=Cell("Lv. —",16,382,164,100,30,null,true,true);percent=Cell("—",14,492,164,110,30,App.Muted,false,true,TextAlignment.Right);
   App.At(canvas,App.Card(null,App.Brush("#F5E8D3"),6),382,207,220,10);progress=App.At(canvas,App.Card(null,App.Gradient("#FFC275","#FFA441"),6),382,207,0,10);
   Cell("下一级预计",12,382,235,88,34,App.Muted);eta=Cell("统计中",18,472,235,130,34,App.Brush("#D87819"),true,false,TextAlignment.Right);
   App.At(canvas,App.Card(),20,307,600,78);string[] labels={"净经验","平均效率","有效时长"};TextBlock[] values=new TextBlock[3];for(int i=0;i<3;i++){double x=20+i*200;Cell(labels[i],12,x+12,315,176,22,App.Muted,false,false,TextAlignment.Center);values[i]=Cell("—",23,x+12,339,176,34,i==0?App.Green:App.Ink,true,true,TextAlignment.Center);if(i>0)App.At(canvas,new Rectangle{Fill=App.Line},x,322,1,47);}gain=values[0];average=values[1];time=values[2];
   App.At(canvas,App.Card(null,App.Gradient("#FFFCF6","#FFF9EF"),14,true),20,397,600,179);Cell("每分钟经验",14,38,405,200,28,null,true);loss=Cell("",11,238,405,362,28,App.Muted,false,false,TextAlignment.Right);chart=new MinuteGraph();App.At(canvas,chart,38,439,564,130);
   start=ReplaceStart("开始记录");App.At(canvas,App.Button("悬浮窗","float",ShowCompact),212,594,128,40);App.At(canvas,App.Button("历史","history",ShowHistory),352,594,128,40);App.At(canvas,App.Button("设置","settings",ShowSettings),492,594,128,40);Refresh();}
  Button ReplaceStart(string label){if(start!=null)canvas.Children.Remove(start);var b=App.Button(label,"stop",Toggle,true);b.Tag=label;App.At(canvas,b,20,594,180,40);return b;}
  void Toggle(){try{if(Engine.Session.Running)Engine.EndSession();else Engine.StartSession();if(history!=null&&history.IsVisible)history.Reload();Refresh();}catch(Exception ex){MessageBox.Show(this,"记录保存失败："+ex.Message);}}
  void Refresh(){if(status==null)return;if(!IsVisible&&compact!=null){compact.Refresh();return;}if(WindowState==WindowState.Minimized&&compact==null)return;var s=Engine.Session;status.Text=Engine.Status;App.SetMapText(map,Engine.MapName,true);map.ToolTip=Engine.MapName;App.SetMapText(region,Engine.Region,false);rate.ToolTip="按最近最多 5 分钟的有效记录估算每小时净经验；不足 5 分钟时使用已有数据，暂停时间不计入。";rate.Text=App.Number(Engine.Rate);rate.FontSize=rate.Text.Length>10?35:54;level.Text=s.Last==null?"Lv. —":"Lv. "+s.Last.Level;percent.Text=s.Last==null?"—":s.Last.Percent.ToString("F2")+"%";progress.Width=s.Last==null?0:Math.Max(0,Math.Min(220,s.Last.Percent*2.2));eta.Text=Engine.Eta;gain.Text=(s.Estimated?"≈ ":"")+App.Number(s.Gain);average.Text=App.Number(s.Average);time.Text=App.Duration(s.Seconds);foreach(var t in new[]{gain,average,time})t.FontSize=t.Text.Length>12?17:23;string label=s.Running?"结束记录":"开始记录";if(!Equals(start.Tag,label))start=ReplaceStart(label);loss.Text=(s.Loss>0?"经验减少 "+App.Number(s.Loss)+" · ":"")+(s.Incomplete?"含缺失区间 · ":"")+"1 格 = 1 分钟";chart.SetData(s.First==null?null:s.Minutes,s.Running&&!s.Paused);if(compact!=null)compact.Refresh();}
  void ShowHistory(){try{if(history==null||!history.IsVisible){history=new History(Engine.DemoMode,Engine){Owner=this};history.Show();}else{history.Reload();history.Activate();}}catch(Exception ex){MessageBox.Show(this,"读取历史失败："+ex.Message);}}
  void ShowSettings(){new Settings(this,Engine){Owner=this}.ShowDialog();}
  void ShowCompact(){if(compact==null){compact=new Compact(Engine,ReturnToMain);compact.Closed+=delegate{compact=null;if(!shuttingDown&&!IsVisible)Show();};}compact.Show();compact.Refresh();Hide();}
  void ReturnToMain(){Show();WindowState=WindowState.Normal;Activate();if(compact!=null)compact.Close();}
  public void RenderAll(){Refresh();Save("main.png");var h=new History(true);h.Show();h.Save("history.png");var c=new Compact(Engine,()=>{});c.Show();c.Refresh();c.Save("compact.png");var settings=new Settings(this,Engine);settings.Show();settings.Save("settings.png");settings.Close();h.Close();c.Close();ClickButton("悬浮窗");if(IsVisible)throw new Exception("Compact entry failed");compact.ClickButton("返回主窗口");if(!IsVisible)throw new Exception("Compact return failed");App.SetFont(!App.Wen,false);UpdateLayout();Save("main-alternate-font.png");App.SetFont(!App.Wen,false);if(Engine.MapName!="Henesys")throw new Exception("Data binding failed");RenderThemes();File.WriteAllText(System.IO.Path.Combine(App.Dir,"ui-checks.txt"),"PASS engine data binding\nPASS compact entry and return\nPASS live font switch\nPASS main/history/settings/compact renders\nDemo data is only enabled by --render or --demo.");}
  void RenderThemes(){string original=Theme.Id;bool font=App.Wen;var gain=Engine.Session.Gain;var history=new History(true);var settings=new Settings(this,Engine);var daily=new DailyWindow(Engine,true);daily.Show();var compact=new Compact(Engine,()=>{});history.Show();settings.Show();compact.Show();foreach(string id in new[]{"mint","warm","sky"}){Theme.Set(id,false);UpdateLayout();Save(id+"-main.png");history.Save(id+"-history.png");settings.Save(id+"-settings.png");compact.Save(id+"-compact.png");daily.Save(id+"-daily.png");if(Theme.Id!=id||App.Wen!=font||Engine.Session.Gain!=gain)throw new Exception("Theme switch changed session or font");}double originalScale=App.UiScale;foreach(bool wen in new[]{false,true}){App.SetFont(wen,false);foreach(double scale in new[]{.8,.9,1.0,1.25,1.5}){App.SetScale(scale,false);UpdateLayout();if(Math.Abs(Width-(640*scale*.9+32))>1||Math.Abs(settings.Width-(480*scale*.9+32))>1)throw new Exception("Scale layout failed");Save("type-"+(wen?"c":"a")+"-"+(scale*100).ToString("0")+".png");settings.Save("settings-"+(wen?"c":"a")+"-"+(scale*100).ToString("0")+".png");}}App.SetFont(font,false);App.SetScale(originalScale,false);Theme.Set(original,false);history.Close();settings.Close();compact.Close();daily.Close();File.WriteAllText(System.IO.Path.Combine(App.Dir,"theme-checks.txt"),"PASS live theme switch across main/history/settings/compact\nPASS font and session preserved\nPASS all three themes rendered\nPASS preview does not save theme preferences");}

 }
 public static class Assets {
  static BitmapImage banner;static BitmapImage icon;public static BitmapImage Icon{get{if(icon==null){icon=new BitmapImage();icon.BeginInit();icon.UriSource=new Uri(System.IO.Path.Combine(App.Dir,"icon.png"));icon.CacheOption=BitmapCacheOption.OnLoad;icon.DecodePixelWidth=128;icon.EndInit();icon.Freeze();}return icon;}}
  public static BitmapImage Banner{get{if(banner==null){banner=new BitmapImage();banner.BeginInit();banner.UriSource=new Uri(System.IO.Path.Combine(App.Dir,"banner.png"));banner.CacheOption=BitmapCacheOption.OnLoad;banner.DecodePixelWidth=1200;banner.EndInit();banner.Freeze();}return banner;}}
 }
 public sealed class Compact:Surface {
  readonly Engine engine;readonly Action back;TextBlock rate,map,time,state;
  public Compact(Engine engine,Action back):base("MapleMeter 暖光版 · 悬浮窗",400,120){this.engine=engine;this.back=back;Topmost=true;ShowInTaskbar=false;Build(back);App.FontChanged+=OnFont;Closed+=delegate{App.FontChanged-=OnFont;};MouseLeftButtonDown+=delegate(object sender,System.Windows.Input.MouseButtonEventArgs e){if(e.ButtonState==System.Windows.Input.MouseButtonState.Pressed)DragMove();};}
  void OnFont(){Reset();Build(back);Refresh();}
  void Build(Action back){App.At(canvas,(FrameworkElement)App.Icon("leaf",17,App.Brush("#EB7848")),16,13);App.At(canvas,App.Text("MapleMeter 暖光版",13,null,true),42,6,207,30);App.At(canvas,App.Button("返回主窗口","back",back),262,5,125,30);rate=App.At(canvas,App.Text("—",36,Theme.Dark?App.Green:App.Ink,true,true),20,44,198,44);state=App.At(canvas,App.Text("预计每小时经验",12,App.Muted),20,89,198,22);App.At(canvas,new Rectangle{Fill=App.Line},231,48,1,54);App.At(canvas,(FrameworkElement)App.Icon("pin",15,App.Brush("#EB7848")),247,56);map=App.At(canvas,App.Text("—",14,null,true,true),275,46,110,30);App.At(canvas,(FrameworkElement)App.Icon("clock",15,App.Muted),247,87);time=App.At(canvas,App.Text("—",14,App.Muted,false,true),275,78,110,30);}
  public void Refresh(){rate.ToolTip="按最近最多 5 分钟的有效记录估算每小时净经验；不足 5 分钟时使用已有数据，暂停时间不计入。";rate.Text=App.Number(engine.Rate);rate.FontSize=rate.Text.Length>9?25:36;App.SetMapText(map,engine.MapName,true);map.ToolTip=engine.MapName;time.Text=App.Duration(engine.Session.Seconds);state.Text="预计每小时经验 · "+engine.Status;}
 }
}
